package org.beehive.jitnn.kernels;

import uk.ac.manchester.tornado.api.KernelContext;
import uk.ac.manchester.tornado.api.math.TornadoMath;
import uk.ac.manchester.tornado.api.types.arrays.FloatArray;
import uk.ac.manchester.tornado.api.types.arrays.IntArray;

/**
 * Tiled FlashAttention-2 forward for head dimensions up to 64, generated by scripts/codegen/flash_tiled.py:
 * a work-group of 16x16 threads owns 64 query rows (staged once in local memory) and streams keys and
 * values through in tiles of 32. Per tile it computes S = Q K^T in 4x2 register blocks, updates the online
 * softmax with 4 threads per row, and accumulates O += P V in 4x4 register blocks, so every K and V element
 * loaded serves 64 queries. Same operands, meta layout, masking and outputs (o and the row logsumexp lse)
 * as {@link FlashKernels64#forward}.
 */
public final class FlashTiled64 {

    public static final int D = 64;
    /** Query rows per work-group. */
    public static final int BQ = 64;
    /** Keys per tile. */
    public static final int BK = 32;
    public static final int THREADS = 256;
    private static final float MASKED = -3.0e38f;

    private FlashTiled64() {
    }

    /** Forward: o and lse. Z * ceil(T / 64) work-groups of 16x16 threads. */
    public static void forward(KernelContext kc, FloatArray q, FloatArray k, FloatArray v, FloatArray mask, FloatArray o, FloatArray lse, int t, int s, int d,
            float scale, int causal, int hasMask, IntArray meta) {
        float[] qs = kc.allocateFloatLocalArray(4160);
        float[] ks = kc.allocateFloatLocalArray(2080);
        float[] vs = kc.allocateFloatLocalArray(2080);
        float[] ss = kc.allocateFloatLocalArray(2112);
        float[] part = kc.allocateFloatLocalArray(256);
        float[] mrow = kc.allocateFloatLocalArray(64);
        float[] lrow = kc.allocateFloatLocalArray(64);
        float[] arow = kc.allocateFloatLocalArray(64);
        int tx = kc.localIdx;
        int ty = kc.localIdy;
        int tid = ty * 16 + tx;
        int qBlocks = (t + 63) / 64;
        int z = kc.groupIdx / qBlocks;
        int q0 = (kc.groupIdx - z * qBlocks) * 64;
        int heads = meta.get(0);
        int b = z / heads;
        int hh = z - b * heads;
        int qBase = meta.get(5) + b * meta.get(6) + hh * meta.get(7);
        int qStr = meta.get(8);
        int kBase = meta.get(9) + b * meta.get(10) + hh * meta.get(11);
        int kStr = meta.get(12);
        int vBase = meta.get(13) + b * meta.get(14) + hh * meta.get(15);
        int vStr = meta.get(16);
        int oBase = meta.get(17) + b * meta.get(18) + hh * meta.get(19);
        int oStr = meta.get(20);
        int mBase = b * meta.get(1) + hh * meta.get(2);
        int mi = meta.get(3);
        int mj = meta.get(4);
        for (int e = tid; e < 4096; e += 256) {
            int r = e / 64;
            int c = e - r * 64;
            float x = 0.0f;
            if ((q0 + r < t) & (c < d)) {
                x = q.get(qBase + (q0 + r) * qStr + c);
            }
            qs[r * 65 + c] = x;
        }
        if (tid < 64) {
            mrow[tid] = MASKED;
            lrow[tid] = 0.0f;
        }
        float acc00 = 0.0f;
        float acc01 = 0.0f;
        float acc02 = 0.0f;
        float acc03 = 0.0f;
        float acc10 = 0.0f;
        float acc11 = 0.0f;
        float acc12 = 0.0f;
        float acc13 = 0.0f;
        float acc20 = 0.0f;
        float acc21 = 0.0f;
        float acc22 = 0.0f;
        float acc23 = 0.0f;
        float acc30 = 0.0f;
        float acc31 = 0.0f;
        float acc32 = 0.0f;
        float acc33 = 0.0f;
        int kEnd = s;
        if (causal != 0) {
            int last = q0 + 64;
            kEnd = last < s ? last : s;
        }
        int row = tid / 4;
        int quarter = tid - row * 4;
        for (int j0 = 0; j0 < kEnd; j0 += 32) {
            for (int e = tid; e < 2048; e += 256) {
                int r = e / 64;
                int c = e - r * 64;
                int j = j0 + r;
                float kv = 0.0f;
                float vv = 0.0f;
                if ((j < s) & (c < d)) {
                    kv = k.get(kBase + j * kStr + c);
                    vv = v.get(vBase + j * vStr + c);
                }
                ks[r * 65 + c] = kv;
                vs[r * 65 + c] = vv;
            }
            kc.localBarrier();
            float s00 = 0.0f;
            float s01 = 0.0f;
            float s10 = 0.0f;
            float s11 = 0.0f;
            float s20 = 0.0f;
            float s21 = 0.0f;
            float s30 = 0.0f;
            float s31 = 0.0f;
            for (int c = 0; c < 64; c++) {
                float a0 = qs[(ty + 0) * 65 + c];
                float a1 = qs[(ty + 16) * 65 + c];
                float a2 = qs[(ty + 32) * 65 + c];
                float a3 = qs[(ty + 48) * 65 + c];
                float k0 = ks[(tx + 0) * 65 + c];
                float k1 = ks[(tx + 16) * 65 + c];
                s00 += a0 * k0;
                s01 += a0 * k1;
                s10 += a1 * k0;
                s11 += a1 * k1;
                s20 += a2 * k0;
                s21 += a2 * k1;
                s30 += a3 * k0;
                s31 += a3 * k1;
            }
            {
                int qi = q0 + ty + 0;
                int j = j0 + tx + 0;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s00 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 0) * 33 + tx + 0] = sv;
            }
            {
                int qi = q0 + ty + 0;
                int j = j0 + tx + 16;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s01 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 0) * 33 + tx + 16] = sv;
            }
            {
                int qi = q0 + ty + 16;
                int j = j0 + tx + 0;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s10 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 16) * 33 + tx + 0] = sv;
            }
            {
                int qi = q0 + ty + 16;
                int j = j0 + tx + 16;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s11 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 16) * 33 + tx + 16] = sv;
            }
            {
                int qi = q0 + ty + 32;
                int j = j0 + tx + 0;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s20 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 32) * 33 + tx + 0] = sv;
            }
            {
                int qi = q0 + ty + 32;
                int j = j0 + tx + 16;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s21 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 32) * 33 + tx + 16] = sv;
            }
            {
                int qi = q0 + ty + 48;
                int j = j0 + tx + 0;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s30 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 48) * 33 + tx + 0] = sv;
            }
            {
                int qi = q0 + ty + 48;
                int j = j0 + tx + 16;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s31 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 48) * 33 + tx + 16] = sv;
            }
            kc.localBarrier();
            float lm = MASKED;
            for (int c = 0; c < 8; c++) {
                float sv = ss[row * 33 + quarter * 8 + c];
                lm = sv > lm ? sv : lm;
            }
            part[tid] = lm;
            kc.localBarrier();
            float mOld = mrow[row];
            float mNew = mOld;
            for (int c = 0; c < 4; c++) {
                float pm = part[row * 4 + c];
                mNew = pm > mNew ? pm : mNew;
            }
            float ls = 0.0f;
            for (int c = 0; c < 8; c++) {
                int at = row * 33 + quarter * 8 + c;
                float sv = ss[at];
                float p = sv > MASKED ? TornadoMath.exp(sv - mNew) : 0.0f;
                ss[at] = p;
                ls += p;
            }
            kc.localBarrier();
            part[tid] = ls;
            kc.localBarrier();
            if (quarter == 0) {
                float alpha = mOld > MASKED ? TornadoMath.exp(mOld - mNew) : 0.0f;
                lrow[row] = lrow[row] * alpha + part[row * 4] + part[row * 4 + 1] + part[row * 4 + 2] + part[row * 4 + 3];
                mrow[row] = mNew;
                arow[row] = alpha;
            }
            kc.localBarrier();
            float al0 = arow[ty + 0];
            acc00 = acc00 * al0;
            acc01 = acc01 * al0;
            acc02 = acc02 * al0;
            acc03 = acc03 * al0;
            float al1 = arow[ty + 16];
            acc10 = acc10 * al1;
            acc11 = acc11 * al1;
            acc12 = acc12 * al1;
            acc13 = acc13 * al1;
            float al2 = arow[ty + 32];
            acc20 = acc20 * al2;
            acc21 = acc21 * al2;
            acc22 = acc22 * al2;
            acc23 = acc23 * al2;
            float al3 = arow[ty + 48];
            acc30 = acc30 * al3;
            acc31 = acc31 * al3;
            acc32 = acc32 * al3;
            acc33 = acc33 * al3;
            for (int kk = 0; kk < 32; kk++) {
                float p0 = ss[(ty + 0) * 33 + kk];
                float p1 = ss[(ty + 16) * 33 + kk];
                float p2 = ss[(ty + 32) * 33 + kk];
                float p3 = ss[(ty + 48) * 33 + kk];
                float v0 = vs[kk * 65 + tx + 0];
                float v1 = vs[kk * 65 + tx + 16];
                float v2 = vs[kk * 65 + tx + 32];
                float v3 = vs[kk * 65 + tx + 48];
                acc00 += p0 * v0;
                acc01 += p0 * v1;
                acc02 += p0 * v2;
                acc03 += p0 * v3;
                acc10 += p1 * v0;
                acc11 += p1 * v1;
                acc12 += p1 * v2;
                acc13 += p1 * v3;
                acc20 += p2 * v0;
                acc21 += p2 * v1;
                acc22 += p2 * v2;
                acc23 += p2 * v3;
                acc30 += p3 * v0;
                acc31 += p3 * v1;
                acc32 += p3 * v2;
                acc33 += p3 * v3;
            }
            kc.localBarrier();
        }
        {
            int r = ty + 0;
            int qi = q0 + r;
            float l = lrow[r];
            float inv = l > 0.0f ? 1.0f / l : 0.0f;
            if ((qi < t) & (tx + 0 < d)) {
                o.set(oBase + qi * oStr + tx + 0, acc00 * inv);
            }
            if ((qi < t) & (tx + 16 < d)) {
                o.set(oBase + qi * oStr + tx + 16, acc01 * inv);
            }
            if ((qi < t) & (tx + 32 < d)) {
                o.set(oBase + qi * oStr + tx + 32, acc02 * inv);
            }
            if ((qi < t) & (tx + 48 < d)) {
                o.set(oBase + qi * oStr + tx + 48, acc03 * inv);
            }
        }
        {
            int r = ty + 16;
            int qi = q0 + r;
            float l = lrow[r];
            float inv = l > 0.0f ? 1.0f / l : 0.0f;
            if ((qi < t) & (tx + 0 < d)) {
                o.set(oBase + qi * oStr + tx + 0, acc10 * inv);
            }
            if ((qi < t) & (tx + 16 < d)) {
                o.set(oBase + qi * oStr + tx + 16, acc11 * inv);
            }
            if ((qi < t) & (tx + 32 < d)) {
                o.set(oBase + qi * oStr + tx + 32, acc12 * inv);
            }
            if ((qi < t) & (tx + 48 < d)) {
                o.set(oBase + qi * oStr + tx + 48, acc13 * inv);
            }
        }
        {
            int r = ty + 32;
            int qi = q0 + r;
            float l = lrow[r];
            float inv = l > 0.0f ? 1.0f / l : 0.0f;
            if ((qi < t) & (tx + 0 < d)) {
                o.set(oBase + qi * oStr + tx + 0, acc20 * inv);
            }
            if ((qi < t) & (tx + 16 < d)) {
                o.set(oBase + qi * oStr + tx + 16, acc21 * inv);
            }
            if ((qi < t) & (tx + 32 < d)) {
                o.set(oBase + qi * oStr + tx + 32, acc22 * inv);
            }
            if ((qi < t) & (tx + 48 < d)) {
                o.set(oBase + qi * oStr + tx + 48, acc23 * inv);
            }
        }
        {
            int r = ty + 48;
            int qi = q0 + r;
            float l = lrow[r];
            float inv = l > 0.0f ? 1.0f / l : 0.0f;
            if ((qi < t) & (tx + 0 < d)) {
                o.set(oBase + qi * oStr + tx + 0, acc30 * inv);
            }
            if ((qi < t) & (tx + 16 < d)) {
                o.set(oBase + qi * oStr + tx + 16, acc31 * inv);
            }
            if ((qi < t) & (tx + 32 < d)) {
                o.set(oBase + qi * oStr + tx + 32, acc32 * inv);
            }
            if ((qi < t) & (tx + 48 < d)) {
                o.set(oBase + qi * oStr + tx + 48, acc33 * inv);
            }
        }
        if ((tid < 64) & (q0 + tid < t)) {
            float l = lrow[tid];
            lse.set(z * t + q0 + tid, l > 0.0f ? mrow[tid] + TornadoMath.log(l) : MASKED);
        }
    }
}
